def solve(grid):
    if not grid or not grid[0]:
        return grid

    rows = len(grid)
    cols = len(grid[0])
    result = [row[:] for row in grid]

    # Find the seed values (non-0, non-8)
    seeds = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0 and grid[r][c] != 8:
                seeds.append((r, c, grid[r][c]))

    if not seeds:
        return result

    # Get the two values in the pattern
    values = list(set(v for r, c, v in seeds))
    if len(values) == 1:
        # Need to find the pair - look at neighbors or assume standard
        pass

    # Actually, let's find what the two alternating values are
    # They should be adjacent in the seed pattern
    val_set = set()
    for r, c, v in seeds:
        for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] != 0 and grid[nr][nc] != 8:
                    val_set.add(grid[nr][nc])

    # The two values for alternating pattern
    all_vals = list(val_set)
    if len(all_vals) >= 2:
        v1, v2 = all_vals[0], all_vals[1]
    else:
        # Fallback: use what we found
        v1 = v2 = seeds[0][2]
        if len(values) >= 2:
            v1, v2 = values[0], values[1]
        else:
            v2 = v1  # degenerate case

    # BFS from all seed positions through 0s
    from collections import deque
    visited = [[False]*cols for _ in range(rows)]
    queue = deque()

    for r, c, v in seeds:
        queue.append((r, c, v))
        visited[r][c] = True

    while queue:
        r, c, v = queue.popleft()
        result[r][c] = v
        next_v = v2 if v == v1 else v1

        for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc]:
                if grid[nr][nc] == 0:  # Can propagate through 0s
                    visited[nr][nc] = True
                    queue.append((nr, nc, next_v))

    return result
